#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> w(n), h(n);
    for (int i = 0; i < n; i++) cin >> w[i] >> h[i];
    vector<long long> cand;
    for (int i = 0; i < n; i++) { cand.push_back(w[i]); cand.push_back(h[i]); }
    long long best = LLONG_MAX;
    for (long long H : cand) {
        int forced = 0; bool ok = true; long long W = 0;
        vector<long long> gain;
        for (int i = 0; i < n && ok; i++) {
            bool st = h[i] <= H, ly = w[i] <= H;   // standing height h, lying height w
            if (!st && !ly) ok = false;
            else if (!st) { forced++; W += h[i]; }  // must lie: width h
            else if (!ly) W += w[i];                // must stand
            else { W += w[i]; if (h[i] < w[i]) gain.push_back(w[i] - h[i]); }
        }
        if (!ok || forced > n / 2) continue;
        sort(gain.rbegin(), gain.rend());
        int budget = n / 2 - forced;
        for (int i = 0; i < (int)gain.size() && i < budget; i++) W -= gain[i];
        best = min(best, W * H);
    }
    cout << best << "\n";
}

