vector<long long> cands(long long a) {       // n with n(n-1)/2 == a (n >= 0)
    vector<long long> r;
    for (long long n = 0; n <= 100000; n++) {
        long long v = n * (n - 1) / 2;
        if (v == a) r.push_back(n);
