    cin >> a00 >> a01 >> a10 >> a11;
    for (long long n0 : cands(a00))
        for (long long n1 : cands(a11)) {
            if (n0 + n1 == 0 || n0 * n1 != a01 + a10) continue;
            vector<long long> z(n1, 0);
            long long rem = a01;
