// Each y comes from some x = y>>k (k >= 0). Feasible for max bound M iff the
// values y>>k(y) <= M can be matched injectively onto their ancestors-or-self.
bool feas(long long M, vector<long long>& X) {
    vector<long long> a(n);
    for (int i = 0; i < n; i++) { long long v = y[i]; while (v > M) v >>= 1; a[i] = v; }
    sort(a.rbegin(), a.rend());
    set<long long> used; X.clear();
    for (long long v : a) {
        while (v >= 1 && used.count(v)) v >>= 1;   // deepest free ancestor-or-self
        if (v == 0) return false;
        used.insert(v); X.push_back(v);
    }
    return true;
}
