    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        if (feas(mid, X)) hi = mid; else lo = mid + 1;
    }
    feas(lo, X);
    for (int i = 0; i < n; i++) cout << X[i] << (i + 1 < n ? ' ' : '\n');
