#include <bits/stdc++.h>
using namespace std;
int main() {
    int m; string s; cin >> m >> s;
    int L = s.size();
    // a set of letter-<=c positions is a valid cover iff every gap (with sentinels 0 and L+1) is <= m
    auto covers = [&](int c) {
        int prev = 0;
        for (int p = 1; p <= L; p++)
            if (s[p - 1] - 'a' <= c) { if (p - prev > m) return false; prev = p; }
        return L + 1 - prev <= m;
    };
    int cs = 0;
    while (!covers(cs)) cs++;
    // every position with letter < cs is taken; add the fewest letter-cs positions to close gaps
    vector<int> fixedPos = {0};
    for (int p = 1; p <= L; p++) if (s[p - 1] - 'a' < cs) fixedPos.push_back(p);
    fixedPos.push_back(L + 1);
    long long x = 0;
    for (size_t g = 0; g + 1 < fixedPos.size(); g++) {
        int a = fixedPos[g], b = fixedPos[g + 1];
        int cur = a;
        while (b - cur > m) {
            int best = -1;   // farthest usable letter-cs position within reach
            for (int q = min(cur + m, b - 1); q > cur; q--) if (s[q - 1] - 'a' == cs) { best = q; break; }
            if (best < 0) { cout << "IMPOSSIBLE\n"; return 0; }
            cur = best; x++;
        }
    }
    vector<long long> cnt(26, 0);
    for (char ch : s) cnt[ch - 'a']++;
    string out;
    for (int c = 0; c < cs; c++) out += string(cnt[c], 'a' + c);
    out += string(x, 'a' + cs);
    cout << out << "\n";
}

