int main() {
    int n, s; cin >> n >> s;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];
    if (n == 1) { cout << (a[1] != 0 ? 1 : 0) << "\n"; return 0; }
    int chiefWrong = (a[s] != 0);
    vector<int> cnt(n + 1, 0);          // non-chief workers reporting depth d (1..n-1)
    int zeros = 0;                       // non-chief workers reporting 0 (always wrong)
    for (int i = 1; i <= n; i++) {
        if (i == s) continue;
        if (a[i] == 0) zeros++; else cnt[a[i]]++;
    }
    // suffix count of non-chief reports > D
    vector<int> greater(n + 2, 0);
    for (int d = n; d >= 0; d--) greater[d] = greater[d + 1] + (d + 1 <= n ? cnt[d + 1] : 0);
    long long best = LLONG_MAX; int gaps = 0;
    for (int D = 1; D <= n - 1; D++) {
        if (cnt[D] == 0) gaps++;
        long long M0 = zeros + greater[D];          // forced mistakes if depths are capped at D
        long long mist = max<long long>(M0, gaps);  // gaps are filled by mistaken or surplus workers
        best = min(best, mist + chiefWrong);
    }
    cout << best << "\n";
}

