#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n, m; cin >> n >> m;
    vector<long long> a(n);
    for (auto& v : a) cin >> v;
    long long half = n / 2;
    set<long long> seen; vector<bool> first(n, false);
    vector<long long> ev, od;                       // unique values per parity
    for (int i = 0; i < n; i++) if (!seen.count(a[i])) {
        seen.insert(a[i]); first[i] = true; (a[i] % 2 ? od : ev).push_back(a[i]);
    }
    // keep up to n/2 per parity, values above m first (they do not use Nikolay's pool)
    auto pick = [&](vector<long long>& v) {
        vector<long long> o;
        for (long long x : v) if (x > m) o.push_back(x);
        for (long long x : v) if (x <= m) o.push_back(x);
        if ((long long)o.size() > half) o.resize(half);
        return o;
    };
    vector<long long> ke = pick(ev), ko = pick(od);
    set<long long> keep(ke.begin(), ke.end()); keep.insert(ko.begin(), ko.end());
    long long smallE = 0, smallO = 0;
    for (long long x : ke) smallE += (x <= m); for (long long x : ko) smallO += (x <= m);
    long long needE = half - (long long)ke.size(), needO = half - (long long)ko.size();
    if (needE > m / 2 - smallE || needO > (m + 1) / 2 - smallO) { cout << -1 << "\n"; return 0; }
    long long nextE = 2, nextO = 1;                 // separate cursors over free Nikolay numbers
    vector<long long> out(a);
    long long swaps = 0;
    for (int i = 0; i < n; i++) {
        if (first[i] && keep.count(a[i])) continue;
        swaps++;
        long long& c = needE > 0 ? nextE : nextO;
        while (keep.count(c)) c += 2;
        out[i] = c; c += 2;
        if (needE > 0) needE--;
    }
    cout << swaps << "\n";
    for (int i = 0; i < n; i++) cout << out[i] << (i + 1 < n ? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<string> A(n), B(n);
    vector<bool> canForce(n);
    for (int i = 0; i < n; i++) {
        string t, h; cin >> t >> h;
        A[i] = t.substr(0, 3);                 // option 1
        B[i] = t.substr(0, 2) + h[0];          // option 2
        canForce[i] = (A[i] != B[i]);          // identical strings count as one choice (option 1)
    }
    vector<int> F(n, 0);                       // 1 = uses option 2 (a real, different string)
    while (true) {
        bool changed = false;
        // rule: if club i uses option 2, no club may use option 1 with the same option-1 name as i
        for (int i = 0; i < n; i++) if (F[i])
            for (int j = 0; j < n; j++) if (j != i && A[j] == A[i] && !F[j]) {
                if (!canForce[j]) { cout << "NO\n"; return 0; }
                F[j] = 1; changed = true;
            }
        map<string, vector<int>> g;
        for (int i = 0; i < n; i++) g[F[i] ? B[i] : A[i]].push_back(i);
        for (auto& [name, v] : g) {
            if (v.size() < 2) continue;
            int fixedCnt = 0;                  // members whose name cannot change any more
            for (int i : v) if (F[i] || !canForce[i]) fixedCnt++;
            if (fixedCnt >= 2) { cout << "NO\n"; return 0; }
            for (int i : v) if (!F[i] && canForce[i]) { F[i] = 1; changed = true; }
        }
        if (!changed) break;
    }
    cout << "YES\n";
    for (int i = 0; i < n; i++) cout << (F[i] ? B[i] : A[i]) << "\n";
}

#include <bits/stdc++.h>
