int main() {
    long long n, w, m; cin >> n >> w >> m;
    // Scale all amounts by m: bottle j covers [j*w*m, (j+1)*w*m), cup i covers [i*n*w, (i+1)*n*w).
    vector<vector<pair<int, long long>>> cups(m);
    bool ok = true;
    for (long long j = 0; j < n && ok; j++) {
        long long bs = j * w * m, be = (j + 1) * w * m;
        int touched = 0;
        for (long long i = 0; i < m; i++) {
            long long cs = i * n * w, ce = (i + 1) * n * w;
            long long lo = max(bs, cs), hi = min(be, ce);
            if (hi > lo) { touched++; cups[i].push_back({(int)j + 1, hi - lo}); }
        }
        if (touched > 2) ok = false;
    }
    if (!ok) { cout << "NO\n"; return 0; }
    cout << "YES\n";
    cout << fixed << setprecision(6);
    for (long long i = 0; i < m; i++) {
        for (auto [b, amt] : cups[i]) cout << b << " " << (double)amt / m << " ";
        cout << "\n";
    }
}

