const int MX = 2000005;
int spf[MX];
int main() {
    for (int i = 2; i < MX; i++) if (!spf[i]) for (int j = i; j < MX; j += i) if (!spf[j]) spf[j] = i;
    int n; cin >> n;
    vector<int> a(n);
    for (auto& v : a) cin >> v;
    vector<char> used(MX, 0);
    auto ok = [&](int x) { while (x > 1) { int p = spf[x]; if (used[p]) return false; while (x % p == 0) x /= p; } return true; };
    auto mark = [&](int x) { while (x > 1) { int p = spf[x]; used[p] = 1; while (x % p == 0) x /= p; } };
    vector<int> b(n);
    int i = 0; bool tight = true;
    for (; i < n && tight; i++) {          // b equals a while it is possible
        int x = a[i];
        while (!ok(x)) x++;
        b[i] = x; mark(x);
        if (x != a[i]) tight = false;
    }
    int cur = 2;                           // afterwards any smallest pairwise-coprime values
    for (; i < n; i++) {
        while (!ok(cur)) cur++;
        b[i] = cur; mark(cur);
    }
    for (int k = 0; k < n; k++) cout << b[k] << (k + 1 < n ? ' ' : '\n');
}

