#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m; cin >> n >> m;
    vector<vector<int>> d(n + 1);            // clockwise distances of candies waiting at each station
    for (int i = 0; i < m; i++) {
        int a, b; cin >> a >> b;
        d[a].push_back((b - a + n) % n);
    }
    // station a: the k-th pickup (k = 0,1,...) happens one lap later each time; largest distances go first
    vector<long long> V(n + 1, -1);
    for (int a = 1; a <= n; a++) {
        if (d[a].empty()) continue;
        sort(d[a].rbegin(), d[a].rend());
        for (int k = 0; k < (int)d[a].size(); k++) V[a] = max(V[a], (long long)k * n + d[a][k]);
    }
    // train starting at s reaches station a first after (a - s) mod n seconds
    for (int s = 1; s <= n; s++) {
        long long best = 0;
        for (int a = 1; a <= n; a++)
            if (V[a] >= 0) best = max(best, (long long)((a - s + n) % n) + V[a]);
        cout << best << (s < n ? ' ' : '\n');
    }
}

