int main() {
    int n; cin >> n;
    string c, a; cin >> c >> a;
    vector<int> g[2][2];                        // g[c][a] = artists of that type
    for (int i = 0; i < n; i++) g[c[i] - '0'][a[i] - '0'].push_back(i + 1);
    int A1 = g[0][1].size() + g[1][1].size();   // total acrobat-capable
    int half = n / 2;
    // group 1 takes p of type 11, q of type 10, r of type 01, s of type 00.
    // Condition: p+q (clowns in group 1) = acrobats in group 2 = A1 - p - r, i.e. q + r = A1 - 2p.
    for (int p = 0; p <= (int)g[1][1].size(); p++) {
        int T = A1 - 2 * p;
        if (T < 0) break;
        int s = half - p - T;
        if (s < 0 || s > (int)g[0][0].size()) continue;
        int q = min<int>(g[1][0].size(), T), r = T - q;
        if (r > (int)g[0][1].size()) continue;
        vector<int> ans;
        for (int i = 0; i < p; i++) ans.push_back(g[1][1][i]);
        for (int i = 0; i < q; i++) ans.push_back(g[1][0][i]);
        for (int i = 0; i < r; i++) ans.push_back(g[0][1][i]);
        for (int i = 0; i < s; i++) ans.push_back(g[0][0][i]);
        for (size_t i = 0; i < ans.size(); i++) cout << ans[i] << (i + 1 < ans.size() ? ' ' : '\n');
        return 0;
    }
    cout << -1 << "\n";
}

