#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n; ll k; vector<ll> c;   // c[1..n]
// Max number of rows of size L: each row uses heights {h, h+1} only.
ll rowsOf(ll L) {
    ll rows = 0, cur = c[1];
    for (int h = 1; h <= n; h++) {
        rows += cur / L;
        ll rem = cur % L;
        if (h == n) break;
        if (rem > 0 && rem + c[h + 1] >= L) { rows++; cur = c[h + 1] - (L - rem); }  // mixed row (h, h+1)
        else cur = c[h + 1];
    }
    return rows;
}
int main() {
    int t; cin >> t;
    while (t--) {
        cin >> n >> k;
        c.assign(n + 2, 0);
        ll total = 0;
        for (int i = 1; i <= n; i++) { cin >> c[i]; total += c[i]; }
        if (total / k < 1 || rowsOf(1) < k) { cout << 0 << "\n"; continue; }
        ll lo = 1, hi = total / k;              // largest L with rowsOf(L) >= k
        while (lo < hi) {
            ll mid = lo + (hi - lo + 1) / 2;
            if (rowsOf(mid) >= k) lo = mid; else hi = mid - 1;
        }
        cout << k * lo << "\n";
    }
}

