using namespace std;
int main() {
    int t; if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int n; if (scanf("%d", &n) != 1) return 0;
        vector<int> cnt(n + 1, 0);
        for (int i = 0; i < n; i++) { int c; if (scanf("%d", &c) != 1) return 0; cnt[c]++; }
        vector<int> mult(n + 1, 0);             // mult[x] = number of categories holding exactly x icons
        for (int c = 1; c <= n; c++) if (cnt[c]) mult[cnt[c]]++;
        int S = n + 1;                          // screen size candidates 2..S
        vector<long long> tot(S + 2, 0), bad(S + 2, 0);
        for (int x = 1; x <= n; x++) {
            if (!mult[x]) continue;
            long long mu = mult[x];
            for (int s = 2; s <= S;) {
                long long p = (x + s - 1) / s;  // fewest screens for x icons at size s
                int e = (p == 1) ? S : (int)min<long long>(S, (x - 1) / (p - 1));
                long long feasEnd = min<long long>(e, x / p + 1);   // p*(s-1) <= x holds for s <= x/p + 1
                tot[s] += mu * p; tot[e + 1] -= mu * p;
                if (feasEnd < e) {
                    int from = (int)max<long long>(s, feasEnd + 1);
                    bad[from] += mu; bad[e + 1] -= mu;
                }
                s = e + 1;
            }
        }
        long long ans = LLONG_MAX, runT = 0, runB = 0;
        for (int s = 2; s <= S; s++) {
            runT += tot[s]; runB += bad[s];
            if (runB == 0) ans = min(ans, runT);
        }
        printf("%lld\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<vector<int>> fr(n + 1, vector<int>(n + 1));   // fr[i][card] = rank of card in friend i's list (0 = best)
    for (int i = 1; i <= n; i++) for (int k = 0; k < n; k++) { int c; cin >> c; fr[i][c] = k; }
    vector<int> al(n + 1);                                 // al[card] = rank in Alexander's list
    for (int k = 0; k < n; k++) { int c; cin >> c; al[c] = k; }
    // Alexander sends friend i his favourite card among {1..j} minus card i, sent right after receiving card j
    for (int i = 1; i <= n; i++) {
        int bestJ = -1, bestRank = INT_MAX;
        for (int j = 1; j <= n; j++) {
            int pick = -1;
            for (int c = 1; c <= j; c++) if (c != i && (pick < 0 || al[c] < al[pick])) pick = c;
            if (pick < 0) continue;
            if (fr[i][pick] < bestRank) { bestRank = fr[i][pick]; bestJ = j; }
        }
        cout << bestJ << (i < n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<int> a(n);
    for (auto& v : a) cin >> v;
    sort(a.begin(), a.end());                  // shortest first is optimal for any chosen set
    const int T = 710, INF = 1e9;              // total writing time of the chosen set (finish <= 720, start at 10)
    vector<vector<int>> dp(T + 1, vector<int>(n + 1, INF));
    dp[0][0] = 0;
    for (int x : a) {                          // 0/1 knapsack in sorted order
        for (int t = T - x; t >= 0; t--) {
            int nt = t + x, fin = 10 + nt;
            int pen = max(0, fin - 360);       // submit at midnight if finished earlier
            for (int k = n - 1; k >= 0; k--) {
                if (dp[t][k] >= INF) continue;
                dp[nt][k + 1] = min(dp[nt][k + 1], dp[t][k] + pen);
            }
        }
    }
    for (int k = n; k >= 0; k--) {
        int best = INF;
        for (int t = 0; t <= T; t++) best = min(best, dp[t][k]);
        if (best < INF) { cout << k << " " << best << "\n"; return 0; }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<string> name(n); vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> name[i] >> a[i];
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return a[x] < a[y]; });
    // insert people from tallest to shortest: each one lands after exactly a[i] taller people
    for (int j = 0; j < n; j++) if (a[ord[j]] > j) { cout << -1 << "\n"; return 0; }
    vector<int> line;
    for (int j = 0; j < n; j++) line.insert(line.begin() + a[ord[j]], ord[j]);
    vector<int> rank(n);
    for (int j = 0; j < n; j++) rank[ord[j]] = j;
    for (int idx : line) cout << name[idx] << " " << 100000 - rank[idx] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Cells at knight-move distance (squared distance 5) conflict; the knight graph is bipartite,
// so the answer is nm minus a maximum matching. Closed form (checked against exact matching up to 12x12):
int main() {
    long long n, m; cin >> n >> m;
    if (n > m) swap(n, m);
    long long ans;
    if (n == 1) ans = m;
    else if (n == 2) { const int tail[4] = {0, 2, 4, 4}; ans = 4 * (m / 4) + tail[m % 4]; }
    else ans = (n * m + 1) / 2;
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; cin >> t;
    while (t--) {
        int n, k; string s;
        cin >> n >> k >> s;
        int N = n / 2, R = 0, bal = 0;          // N = number of bracket pairs, R = top-level blocks
        for (char ch : s) {
            bal += (ch == '(') ? 1 : -1;
            if (bal == 0) R++;
        }
        // type-1 ops remove one top-level block each; each type-2 op removes one inner "()" pair
        cout << min(k, N - R) + R << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> a(n + 2, 0);
    for (int i = 1; i <= n; i++) cin >> a[i];
    vector<int> open;                          // start index of each currently open interval
    vector<pair<int, int>> calls;
    a[n + 1] = 0;                              // close everything at the end
    for (int i = 1; i <= n + 1; i++) {
        long long cur = open.size();
        if (a[i] > cur) for (long long k = 0; k < a[i] - cur; k++) open.push_back(i);
        else for (long long k = 0; k < cur - a[i]; k++) {
            int s = open.back(); open.pop_back();
            calls.push_back({s, i - 1});       // interval ends just before position i
        }
    }
    cout << calls.size() << "\n";
    for (auto [l, r] : calls) cout << l << " " << r << "\n";
}
